<?php
namespace App\Services;
use App\Models\PengajuanPerubahan; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class PengajuanPerubahanService { public function ajukan(int $idSiswa,int $idPeriode,string $alasan,array $detail):PengajuanPerubahan { return DB::transaction(function()use($idSiswa,$idPeriode,$alasan,$detail){$p=PengajuanPerubahan::create(['id_siswa'=>$idSiswa,'id_periode_update'=>$idPeriode,'alasan'=>$alasan,'status_pengajuan'=>'menunggu','tgl_pengajuan'=>now()]); foreach($detail as $d){ if(!in_array($d['nama_field'],['nama_lengkap','jenis_kelamin','tempat_lahir','tanggal_lahir','email','no_telepon','nis','nisn','nik'],true)) throw ValidationException::withMessages(['detail'=>'Field tidak diizinkan']); $p->detail()->create(['nama_field'=>$d['nama_field'],'nilai_lama'=>$d['nilai_lama']??null,'nilai_baru'=>$d['nilai_baru']??null,'bukti_path'=>$d['bukti_path']??null]); } return $p->load('detail'); },3); } public function putuskan(int $id,int $petugas, string $keputusan,?string $catatan=null):void { if(!in_array($keputusan,['disetujui','ditolak','perlu_perbaikan'],true)) throw ValidationException::withMessages(['status'=>'Keputusan tidak valid']); DB::transaction(function()use($id,$petugas,$keputusan,$catatan){ $p=PengajuanPerubahan::query()->lockForUpdate()->findOrFail($id); if($p->status_pengajuan!=='menunggu') throw ValidationException::withMessages(['status'=>'Pengajuan sudah diproses']); if($keputusan==='disetujui') { DB::statement('CALL sp_setujui_pengajuan(?, ?, ?)',[$id,$petugas,$catatan]); return; } $p->update(['status_pengajuan'=>$keputusan,'id_pemeriksa'=>$petugas,'catatan_pemeriksa'=>$catatan,'diputuskan_pada'=>now()]); },3); } }
